        var v = Math.max(30, Math.min(100, parseInt(state.resolutionScale, 10) || 100));
        // Dynamic Resolution may hold it lower for now (dynScale is 100 when it isn't)
        var dynOn = !!state.dynResOn && typeof dynScale === 'number' && dynScale < v;
        if (dynOn) v = dynScale;
